const r = await tools.mcp__executor_personal__execute({code:`const teamId = "REDACTED";
const projectId = "REDACTED";
const api = tools.vercel_api.user.personalvercelapi;
const [project, envs, deployments, aliases] = await Promise.all([
  api.projects.getProject({ idOrName: projectId, teamId }),
  api.projects.filterProjectEnvs({ idOrName: projectId, teamId }),
  api.deployments.getDeployments({ projectId, teamId, target: "production", limit: 20 }),
  api.aliases.listAliases({ projectId, teamId, limit: 20 })
]);
const productionEnvs = (envs.envs ?? envs).filter((env) => (Array.isArray(env.target) ? env.target : [env.target]).includes("production")).map((env) => ({ key: env.key, type: env.type, target: env.target }));
const summarizeDeployment = (deployment) => ({ id: deployment.uid ?? deployment.id, readyState: deployment.readyState, target: deployment.target, meta: deployment.meta ? { githubCommitSha: deployment.meta.githubCommitSha } : undefined, urlPresent: Boolean(deployment.url), createdAt: deployment.createdAt });
return {
  project: { id: project.id, name: project.name, accountId: project.accountId, ssoProtection: project.ssoProtection, latestDeployments: project.latestDeployments?.map(summarizeDeployment) },
  productionEnvs,
  deployments: (deployments.deployments ?? deployments).map(summarizeDeployment),
  aliases: (aliases.aliases ?? aliases).map((alias) => ({ alias: alias.alias, deploymentId: alias.deploymentId, projectId: alias.projectId }))
};`}); text(r);

